/** A period was refused: a blank or taken name, a bad date, a to-date before its from-date, or an overlap with another period. */
public class InvalidPeriodException extends Exception {

    public InvalidPeriodException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;

/** A sheet's period: a name unique on the sheet, from and to dates inclusive. */
public record Period(String sheetId, String name, LocalDate from, LocalDate to) {

    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }
}
package net.officefloor.hq.app.period;

/** The body of a period being added: the name and the from and to dates as typed. */
public record PeriodRequest(String name, String from, String to) {
}
package net.officefloor.hq.app.period;

/** A period as the screen sees it: the dates as yyyy-mm-dd. */
public record PeriodResponse(String name, String from, String to) {

    public static PeriodResponse from(Period period) {
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString());
    }
}
package net.officefloor.hq.app.period;

import java.sql.Date;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The store of periods, kept per sheet. */
@Repository
public class Periods {

    private static final RowMapper<Period> ROW = (rs, n) -> new Period(rs.getString("sheet_id"),
            rs.getString("name"), rs.getDate("from_date").toLocalDate(), rs.getDate("to_date").toLocalDate());

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
    }

    public void add(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()));
    }
}
